<?php
declare(strict_types=1);
function analytics_charts(string $start,string $end): array {
 $charts=[];$args=[bid(),$start,$end];$add=function(string $title,string $type,array $rows,string $label,array $series,bool $currency=false,string $link='reports.php')use(&$charts){$datasets=[];$colors=['#0ea5e9','#61bca0','#f1bf68','#91a4bc'];foreach($series as $key=>$name){$datasets[]=['label'=>$name,'data'=>array_map(fn($r)=>(float)($r[$key]??0),$rows),'backgroundColor'=>count($series)===1?['#0ea5e9','#65c5ed','#a2ddf5','#61bca0','#f1bf68','#91a4bc']:$colors[count($datasets)%4],'borderColor'=>$colors[count($datasets)%4],'borderWidth'=>$type==='line'?2:0,'tension'=>.3,'pointRadius'=>2];}$charts[]=['title'=>$title,'type'=>$type,'labels'=>array_column($rows,$label),'datasets'=>$datasets,'currency'=>$currency,'link'=>$link,'period'=>[$start,$end]];};
 if(can('payments.view')&&can('expenses.view')){$r=rows("SELECT period,SUM(receipts) receipts,SUM(expenses) expenses FROM (SELECT DATE_FORMAT(payment_date,'%Y-%m') period,SUM(amount) receipts,0 expenses FROM payments WHERE business_id=? AND reversed_at IS NULL AND payment_date BETWEEN ? AND ? GROUP BY period UNION ALL SELECT DATE_FORMAT(expense_date,'%Y-%m') period,0 receipts,SUM(amount) expenses FROM expenses WHERE business_id=? AND status='Active' AND expense_date BETWEEN ? AND ? GROUP BY period) flow GROUP BY period ORDER BY period",[...$args,...$args]);$add('Actual cash inflows & outflows','bar',$r,'period',['receipts'=>'Cash received','expenses'=>'Cash paid for expenses'],true,'reports.php?report=summary');}
 if(can('invoices.view')&&can('payments.view')){require_once __DIR__.'/reports.php';$add('Receivables aging','bar',report_data('aging',$start,$end),'aging_bucket',['outstanding'=>'Outstanding balance'],true,'reports.php?report=aging');}
 if(can('leads.view')){$pipeline=rows("SELECT stage,COUNT(*) leads,SUM(value) value FROM leads WHERE business_id=? AND status='Active' AND DATE(created_at) BETWEEN ? AND ? GROUP BY stage ORDER BY FIELD(stage,'New','Qualified','Proposal','Negotiation','Won','Lost')",$args);$add('Pipeline value by stage','bar',$pipeline,'stage',['value'=>'Deal value'],true,'leads.php');$add('Lead conversion by current stage','bar',$pipeline,'stage',['leads'=>'Leads'],false,'reports.php?report=leads');}
 if(can('customers.view')){$r=rows("SELECT DATE_FORMAT(created_at,'%Y-%m') period,COUNT(*) customers FROM customers WHERE business_id=? AND status<>'Archived' AND DATE(created_at) BETWEEN ? AND ? GROUP BY period ORDER BY period",$args);$add('Customer acquisition','line',$r,'period',['customers'=>'New customers'],false,'customers.php');}
 if(can('customers.view')&&can('invoices.view')){$r=rows("SELECT c.name customer,SUM(d.total) billed FROM customers c JOIN documents d ON d.customer_id=c.id AND d.business_id=c.business_id AND d.type='invoice' AND d.status='Issued' WHERE c.business_id=? AND d.issue_date BETWEEN ? AND ? GROUP BY c.id ORDER BY billed DESC LIMIT 5",$args);$add('Top customers by billed amount','bar',$r,'customer',['billed'=>'Invoiced value'],true,'reports.php?report=customers');$r=rows("SELECT CASE WHEN EXISTS(SELECT 1 FROM documents old WHERE old.customer_id=d.customer_id AND old.business_id=d.business_id AND old.type='invoice' AND old.status='Issued' AND old.issue_date<?) THEN 'Returning' ELSE 'New' END customer_type,COUNT(DISTINCT d.customer_id) customers FROM documents d WHERE d.business_id=? AND d.issue_date BETWEEN ? AND ? AND d.type='invoice' AND d.status='Issued' GROUP BY customer_type",[$start,...$args]);$add('New vs. returning billed customers','doughnut',$r,'customer_type',['customers'=>'Customers'],false,'reports.php?report=customers');}
 if(can('products.view')&&can('invoices.view')){$r=rows("SELECT COALESCE(p.name,i.description) item,SUM(i.total) billed FROM document_items i JOIN documents d ON d.id=i.document_id LEFT JOIN products p ON p.id=i.product_id AND p.business_id=d.business_id WHERE d.business_id=? AND d.issue_date BETWEEN ? AND ? AND d.type='invoice' AND d.status='Issued' GROUP BY item ORDER BY billed DESC LIMIT 6",$args);$add('Product & service performance','bar',$r,'item',['billed'=>'Billed amount'],true,'reports.php?report=products');}
 if(can('expenses.view')){$r=rows("SELECT category,SUM(amount) expenses FROM expenses WHERE business_id=? AND expense_date BETWEEN ? AND ? AND status='Active' GROUP BY category ORDER BY expenses DESC",$args);$add('Expenses by category','doughnut',$r,'category',['expenses'=>'Recorded expenses'],true,'reports.php?report=expenses');}
 if(can('quotations.view')){$r=rows("SELECT CASE WHEN i.id IS NOT NULL THEN 'Converted' ELSE q.status END outcome,COUNT(*) quotations FROM documents q LEFT JOIN documents i ON i.source_id=q.id AND i.business_id=q.business_id WHERE q.business_id=? AND q.issue_date BETWEEN ? AND ? AND q.type='quotation' GROUP BY outcome",$args);$add('Quotation outcomes','doughnut',$r,'outcome',['quotations'=>'Quotations'],false,'reports.php?report=quotations');}
 if(can('payments.view')){$r=rows("SELECT DATE_FORMAT(payment_date,'%Y-%m-%d') period,SUM(amount) receipts FROM payments WHERE business_id=? AND payment_date BETWEEN ? AND ? AND reversed_at IS NULL GROUP BY period ORDER BY period",$args);$add('Payment collection trend','line',$r,'period',['receipts'=>'Cash received'],true,'reports.php?report=payments');}
 if(can('invoices.view')){$r=rows("SELECT DATE_FORMAT(issue_date,'%Y-%m') period,SUM(total) revenue FROM documents WHERE business_id=? AND issue_date BETWEEN ? AND ? AND type='invoice' AND status='Issued' GROUP BY period ORDER BY period",$args);$add('Monthly invoiced revenue','bar',$r,'period',['revenue'=>'Invoiced revenue'],true,'reports.php?report=revenue');}
 return $charts;
}
